\set ON_ERROR_STOP off

-- ============================================================
-- SETUP
-- ============================================================
BEGIN;
SET LOCAL request.jwt.claim.sub = '10000000-0000-0000-0000-000000000001';
CREATE TEMP TABLE IF NOT EXISTS t_reg (nome text primary key, ok bool NOT NULL, detalhe text);
CREATE TEMP TABLE IF NOT EXISTS t_state (k text primary key, v text);

CREATE OR REPLACE FUNCTION pg_temp.check(p_nome text, p_ok boolean, p_detalhe text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
