    ON CONFLICT (nome) DO UPDATE SET ok = EXCLUDED.ok, detalhe = EXCLUDED.detalhe;
  IF p_ok THEN RAISE NOTICE 'PASS  %', p_nome;
  ELSE RAISE NOTICE 'FAIL  %  [%]', p_nome, p_detalhe; END IF;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.expect_error(p_nome text, p_sql text, p_msg text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  BEGIN
    EXECUTE p_sql;
    PERFORM pg_temp.check(p_nome, false, 'não lançou exceção');
  EXCEPTION WHEN others THEN
    IF p_msg IS NULL OR position(coalesce(p_msg,'') in SQLERRM) > 0 THEN
      PERFORM pg_temp.check(p_nome, true, substring(SQLERRM, 1, 120));
    ELSE
      PERFORM pg_temp.check(p_nome, false, 'msg inesperada: ' || substring(SQLERRM, 1, 160));
    END IF;
  END;
END $$;

INSERT INTO auth.users(id, email) VALUES
  ('10000000-0000-0000-0000-000000000001', 'admin@fabrica.test');
INSERT INTO public.organizations(id, name, slug) VALUES
  ('20000000-0000-0000-0000-000000000001', 'Fábrica Teste', 'fabrica-teste'),
  ('20000000-0000-0000-0000-000000000002', 'Outra Fábrica', 'outra-fabrica');
INSERT INTO public.profiles(id, full_name) VALUES
  ('10000000-0000-0000-0000-000000000001', 'Admin Teste');
INSERT INTO public.organization_members(organization_id, user_id, role) VALUES
  ('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'admin'),
  ('20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'admin');
INSERT INTO public.products(id, organization_id, code, name, status) VALUES
  ('40000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', 'P-001', 'Sapatilha', 'ACTIVE'),
  ('40000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', 'P-002', 'Tênis', 'ACTIVE');
INSERT INTO public.product_variants(id, organization_id, product_id, sku, size, color, status) VALUES
  ('50000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001', 'SKU-001', '34', 'Rosa', 'ACTIVE'),
  ('50000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', '40000000-0000-0000-0000-000000000002', 'SKU-002', '40', 'Preto', 'ACTIVE');
INSERT INTO public.inventory_locations(id, organization_id, code, name, type, status) VALUES
