COMMIT;

-- ============================================================
-- A. POST DE MOVIMENTO e invariantes do trigger
-- ============================================================
BEGIN;
SET LOCAL request.jwt.claim.sub = '10000000-0000-0000-0000-000000000001';
DO $$
DECLARE v jsonb; v_id uuid; v_saldo numeric;
BEGIN
  -- Abertura de estoque +100
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001', 'OPENING_BALANCE', 100,
    'abertura', now(), 'un');
  v_id := (v->>'movement_id')::uuid;
  PERFORM pg_temp.check('A1 abertura +100 (deduped=false)', NOT (v->>'deduped')::boolean);
  PERFORM pg_temp.check('A2 movement_id presente', v_id IS NOT NULL);
  v_saldo := public.inventory_get_balance(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001');
  PERFORM pg_temp.check('A3 saldo=100 após abertura', v_saldo = 100, 'saldo=' || v_saldo);

  -- AJUSTE DE ENTRADA aceito pela RPC (correção da falha identificada)
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001', 'ADJUSTMENT_IN', 50,
    'divergência encontrada', now(), 'un');
  PERFORM pg_temp.check('A4 ADJUSTMENT_IN aceito pelo post (fix)', NOT (v->>'deduped')::boolean);
  v_saldo := public.inventory_get_balance(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001');
  PERFORM pg_temp.check('A5 saldo=150 após ajuste +50', v_saldo = 150, 'saldo=' || v_saldo);

  -- Ajuste de saída
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001', 'ADJUSTMENT_OUT', 30,
    'sobra física', now(), 'un');
  v_saldo := public.inventory_get_balance(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001');
  PERFORM pg_temp.check('A6 saldo=120 após ajuste -30', v_saldo = 120, 'saldo=' || v_saldo);

  -- Perda (LOSS) exige motivo
  PERFORM pg_temp.expect_error('A7 LOSS sem motivo é rejeitado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''LOSS'',5,NULL,now(),''un'')',
    'Motivo obrigatório');

  -- Quantidade inválida
  PERFORM pg_temp.expect_error('A8 quantity=0 rejeitado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_IN'',0,''x'')',
    'Quantidade');
  PERFORM pg_temp.expect_error('A9 quantity negativa rejeitada',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_IN'',-5,''x'')',
    'Quantidade');

  -- Unidade operacional
  PERFORM pg_temp.expect_error('A10 unit!=un rejeitado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_IN'',5,''x'',now(),''kg'')',
    'Unidade operacional');

  -- Tipos dedicados rejeitados no post direto
  PERFORM pg_temp.expect_error('A11 TRANSFER_IN dedicado rejeitado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''TRANSFER_IN'',5)',
    'dedicada');
  PERFORM pg_temp.expect_error('A12 PARTNER_SHIPMENT dedicado rejeitado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''PARTNER_SHIPMENT'',5)',
    'dedicada');
  PERFORM pg_temp.expect_error('A13 REVERSAL dedicado rejeitado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''REVERSAL'',5)',
    'dedicada');

  -- Direção incompatível
  PERFORM pg_temp.expect_error('A14 direção incompatível rejeitada',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''OPENING_BALANCE'',5,NULL,now(),''un'',NULL,NULL,NULL,NULL,''OUT'')',
    'Direção incompatível');

  -- Variante de outra organização (não existe nesta org)
  PERFORM pg_temp.expect_error('A15 variante de outra org rejeitada',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000002'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_IN'',5,''x'')',
    'Variante não encontrada');

  -- Localização inativa
  UPDATE public.inventory_locations SET status = 'INACTIVE' WHERE id = '30000000-0000-0000-0000-000000000002';
  PERFORM pg_temp.expect_error('A16 localização inativa rejeitada',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000002'',''ADJUSTMENT_IN'',5,''x'')',
    'Localização');
  UPDATE public.inventory_locations SET status = 'ACTIVE' WHERE id = '30000000-0000-0000-0000-000000000002';

  -- Idempotência
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001', 'ADJUSTMENT_IN', 10,
    'idempotente', now(), 'un', NULL, NULL, NULL, 'evt-abc-1');
  PERFORM pg_temp.check('A17 idempotência 1ª chamada cria', NOT (v->>'deduped')::boolean);
  PERFORM pg_temp.check('A18 saldo=130 após +10', public.inventory_get_balance(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001') = 130);
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001', 'ADJUSTMENT_IN', 10,
    'idempotente', now(), 'un', NULL, NULL, NULL, 'evt-abc-1');
  PERFORM pg_temp.check('A19 idempotência 2ª chamada dedupe', (v->>'deduped')::boolean);
  PERFORM pg_temp.check('A20 saldo continua 130 após dedupe', public.inventory_get_balance(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001') = 130);
  PERFORM pg_temp.expect_error('A21 idempotência com conteúdo diferente',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_OUT'',7,''idempotente'',now(),''un'',NULL,NULL,NULL,''evt-abc-1'')',
    'Chave de idempotência já usada');

  -- Trigger de imutabilidade
  SELECT id INTO v_id FROM public.inventory_movements
    WHERE organization_id = '20000000-0000-0000-0000-000000000001'
    ORDER BY created_at LIMIT 1;
  PERFORM pg_temp.expect_error('A22 UPDATE em movimento bloqueado',
    format('UPDATE public.inventory_movements SET reason = ''hack'' WHERE id = %L', v_id),
    'não é editado');
  PERFORM pg_temp.expect_error('A23 DELETE em movimento bloqueado',
    format('DELETE FROM public.inventory_movements WHERE id = %L', v_id),
    'não é editado');

  -- Override de saldo negativo é sempre recusado
  PERFORM pg_temp.expect_error('A24 allow_negative_override sempre recusado',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_OUT'',5000,''x'',now(),''un'',NULL,NULL,NULL,NULL,NULL,NULL,true)',
    'Override de saldo negativo');
END $$;
COMMIT;

-- ============================================================
-- B. SALDO NEGATIVO CONTROLADO
-- ============================================================
BEGIN;
SET LOCAL request.jwt.claim.sub = '10000000-0000-0000-0000-000000000001';
DO $$
DECLARE v jsonb;
BEGIN
  -- Por padrão allow_negative = false: saída acima do saldo bloqueada
  PERFORM pg_temp.expect_error('B1 saldo negativo bloqueado por padrão',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''SALE'',9999,''venda'')',
    'Saldo insuficiente');

  -- Habilita permitido: OUT pode ficar negativo (com permissão e auditoria)
  INSERT INTO public.organization_inventory_settings(organization_id, allow_negative_inventory, updated_by)
  VALUES ('20000000-0000-0000-0000-000000000001', true, '10000000-0000-0000-0000-000000000001')
  ON CONFLICT (organization_id) DO UPDATE SET allow_negative_inventory = true;
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001', 'SALE', 200, 'venda grande');
  PERFORM pg_temp.check('B2 saída negativa permitida quando habilitada',
    NOT (v->>'deduped')::boolean,
    coalesce(v->>'warning','sem warning'));
  PERFORM pg_temp.check('B3 warning de estoque negativo auditado',
    position('negativo' in coalesce(v->>'warning','')) > 0);
  PERFORM pg_temp.check('B4 saldo ficou negativo (-70)',
    public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
      '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001') = -70);
  PERFORM pg_temp.check('B5 auditoria negative_warning gravada',
    EXISTS (SELECT 1 FROM public.audit_log
      WHERE organization_id='20000000-0000-0000-0000-000000000001'
        AND action='inventory.negative_warning'));

  -- Desabilita de novo
  UPDATE public.organization_inventory_settings SET allow_negative_inventory = false
    WHERE organization_id = '20000000-0000-0000-0000-000000000001';
  PERFORM pg_temp.expect_error('B6 volta a bloquear após desabilitar',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''SALE'',9999,''venda 2'')',
    'Saldo insuficiente');
END $$;
COMMIT;

-- ============================================================
-- C. TRANSFERÊNCIA E REMESSA (par OUT+IN atômico)
-- ============================================================
BEGIN;
SET LOCAL request.jwt.claim.sub = '10000000-0000-0000-0000-000000000001';
DO $$
DECLARE v jsonb; v_tf uuid; v_sal text; v_prev_fab numeric; v_prev_wh numeric;
BEGIN
  -- Saldo atual na Fábrica é -70 (grupo B). Cria um estado limpo: abertura nova em CD + remessa para parceiro.
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000002', 'OPENING_BALANCE', 100, 'abertura CD');
  PERFORM pg_temp.check('C1 abertura CD 100', NOT (v->>'deduped')::boolean);

  -- Transferência CD -> Fábrica 30 (repõe parcialmente o saldo negativo da fábrica)
  v_prev_wh := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');
  v := public.inventory_post_transfer(
    '20000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000001',
    jsonb_build_array(jsonb_build_object('variant_id','50000000-0000-0000-0000-000000000001','quantity',30)),
    'TRANSFER', 'cobertura de saldo');
  PERFORM pg_temp.check('C2 transferência criada (deduped=false)', NOT (v->>'deduped')::boolean, v->>'transfer_id');
  v_tf := (v->>'transfer_id')::uuid;
  PERFORM pg_temp.check('C3 transfer_id presente', v_tf IS NOT NULL);
  PERFORM pg_temp.check('C4 dupla leitura do saldo origem',
    public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
      '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002') = v_prev_wh - 30);
  PERFORM pg_temp.check('C5 origem Fábrica subiu para -40',
    public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
      '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001') = -40);
  PERFORM pg_temp.check('C6 pares OUT+IN na mesma transação (2 movimentos)',
    (SELECT count(*) = 2 FROM public.inventory_movements
      WHERE organization_id='20000000-0000-0000-0000-000000000001'
        AND reference_type='TRANSFER' AND reference_id=v_tf));

  -- origem = destino
  PERFORM pg_temp.expect_error('C7 origem=destino rejeitada',
    'SELECT public.inventory_post_transfer(''20000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000002'',''30000000-0000-0000-0000-000000000002'',jsonb_build_array(jsonb_build_object(''variant_id'',''50000000-0000-0000-0000-000000000001'',''quantity'',1)),''TRANSFER'')',
    'Origem e destino devem ser diferentes');

  -- Transferência com saldo insuficiente na origem
  UPDATE public.organization_inventory_settings SET allow_negative_inventory = false
    WHERE organization_id = '20000000-0000-0000-0000-000000000001';
  PERFORM pg_temp.expect_error('C8 saldo insuficiente na origem bloqueia transferência',
    'SELECT public.inventory_post_transfer(''20000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000002'',jsonb_build_array(jsonb_build_object(''variant_id'',''50000000-0000-0000-0000-000000000001'',''quantity'',500)),''TRANSFER'')',
    'Saldo insuficiente');

  -- item com quantity inválida
  PERFORM pg_temp.expect_error('C9 item de transferência inválido',
    'SELECT public.inventory_post_transfer(''20000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000002'',''30000000-0000-0000-0000-000000000001'',jsonb_build_array(jsonb_build_object(''variant_id'',''50000000-0000-0000-0000-000000000001'',''quantity'',0)),''TRANSFER'')',
    'Quantidade');

  -- Remessa para parceiro exige destino PARTNER
