  v := public.inventory_post_transfer(
    '20000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000003',
    jsonb_build_array(jsonb_build_object('variant_id','50000000-0000-0000-0000-000000000001','quantity',20)),
    'PARTNER_SHIPMENT', 'consignação');
  PERFORM pg_temp.check('C11 remessa PARTNER_SHIPMENT ok', NOT (v->>'deduped')::boolean);
  PERFORM pg_temp.check('C12 parceiro recebeu 20 (posse)',
    public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
      '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000003') = 20);
  PERFORM pg_temp.check('C13 nenhum movimento SALE nasceu da remessa',
    NOT EXISTS (SELECT 1 FROM public.inventory_movements
      WHERE organization_id='20000000-0000-0000-0000-000000000001'
