-- ============================================================
-- D. REVERSÃO (original permanece POSTED; compensação cancela efeito)
-- ============================================================
BEGIN;
SET LOCAL request.jwt.claim.sub = '10000000-0000-0000-0000-000000000001';
DO $$
DECLARE v jsonb; v_mid uuid; v_cnt uuid; v_orig_status text;
        v_before_fab numeric; v_before_wh numeric; v_after_fab numeric; v_after_wh numeric;
        v_rev integer; r record;
BEGIN
  -- Reverter a transferência CD->Fábrica 30 (estorna por inteiro)
  SELECT id INTO v_mid FROM public.inventory_movements
    WHERE organization_id='20000000-0000-0000-0000-000000000001'
      AND reference_type='TRANSFER' AND direction='OUT' ORDER BY created_at LIMIT 1;
  v_before_fab := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001');
  v_before_wh := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');

  v := public.inventory_reverse_movement('20000000-0000-0000-0000-000000000001', v_mid, 'estorno da transferência');
  PERFORM pg_temp.check('D1 reversão de transferência cria 2 compensações',
    jsonb_array_length(v->'movement_ids') = 2, v->>'movement_ids');

  v_after_fab := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001');
  v_after_wh := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');
  PERFORM pg_temp.check('D2 saldo Fábrica voltou ao anterior', v_after_fab = v_before_fab,
    v_before_fab || ' -> ' || v_after_fab);
  PERFORM pg_temp.check('D3 saldo CD voltou ao anterior', v_after_wh = v_before_wh,
    v_before_wh || ' -> ' || v_after_wh);

  -- Original de transferência continua POSTED (nunca REVERSED)
  SELECT status INTO v_orig_status FROM public.inventory_movements WHERE id = v_mid;
  PERFORM pg_temp.check('D4 original da transferência permanece POSTED',
    v_orig_status = 'POSTED', 'status=' || v_orig_status);
  PERFORM pg_temp.check('D5 não existe movimento REVERSED no banco',
    NOT EXISTS (SELECT 1 FROM public.inventory_movements WHERE status='REVERSED'));

  -- Reversão idempotente: segunda chamada retorna a mesma compensação
  v := public.inventory_reverse_movement('20000000-0000-0000-0000-000000000001', v_mid, 'de novo');
  PERFORM pg_temp.check('D6 segunda reversão é deduped', (v->>'deduped')::boolean);

  -- Reverter um movimento normal (abertura IN) — cria 1 compensação OUT
  SELECT id INTO v_mid FROM public.inventory_movements
    WHERE organization_id='20000000-0000-0000-0000-000000000001'
      AND movement_type='OPENING_BALANCE' AND location_id='30000000-0000-0000-0000-000000000002'
    ORDER BY created_at LIMIT 1;
  v_before_wh := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');
  v := public.inventory_reverse_movement('20000000-0000-0000-0000-000000000001', v_mid, 'errei abertura');
  PERFORM pg_temp.check('D7 reversão simples cria 1 compensação',
    jsonb_array_length(v->'movement_ids') = 1, v->>'movement_ids');
  PERFORM pg_temp.check('D8 saldo CD descresce após estorno da abertura',
    public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
      '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002') = v_before_wh - 100);

  -- Reverter a compensação é proibido
  v := public.inventory_reverse_movement('20000000-0000-0000-0000-000000000001', (v->>'movement_id')::uuid, 'x');
  PERFORM pg_temp.expect_error('D9 compensação não pode ser estornada',
    format('SELECT public.inventory_reverse_movement(''20000000-0000-0000-0000-000000000001'', %L, ''x'')', (v->>'movement_id')::uuid),
    'Uma compensação não pode ser estornada');

  -- Movimento inexistente
  PERFORM pg_temp.expect_error('D10 movimento inexistente',
    'SELECT public.inventory_reverse_movement(''20000000-0000-0000-0000-000000000001'',''ffffffff-ffff-ffff-ffff-ffffffffffff'',''x'')',
    'Movimento não encontrado');

  -- Motivo obrigatório
  PERFORM pg_temp.expect_error('D11 motivo obrigatório',
    format('SELECT public.inventory_reverse_movement(''20000000-0000-0000-0000-000000000001'', %L, ''  '')', v_mid),
    'Motivo obrigatório');
END $$;
COMMIT;

-- ============================================================
-- E. CONTAGEM FÍSICA (bloqueia localização + ajustes por divergência)
-- ============================================================
BEGIN;
SET LOCAL request.jwt.claim.sub = '10000000-0000-0000-0000-000000000001';
DO $$
DECLARE v jsonb; v_cid uuid; v_item uuid; v_res jsonb; v_before numeric; v_after numeric;
BEGIN
  -- Estado: CD tem abertura 100 (?) menos estorno... calculamos via balanço
  v_before := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');

  -- Iniciar contagem no CD
  v := public.inventory_start_count('20000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000002');
  v_cid := (v->>'id')::uuid;
  PERFORM pg_temp.check('E1 contagem iniciada', v_cid IS NOT NULL);
  PERFORM pg_temp.check('E2 snapshot de itens criado',
    (v->>'items')::int >= 1, 'items=' || v->>'items');

  -- Localização bloqueada para movimentação durante contagem
  PERFORM pg_temp.expect_error('E3 movimentação bloqueada durante contagem',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000002'',''ADJUSTMENT_IN'',5,''x'')',
    'Localização em contagem');
  PERFORM pg_temp.expect_error('E4 transferência da localização bloqueada',
    'SELECT public.inventory_post_transfer(''20000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000002'',''30000000-0000-0000-0000-000000000001'',jsonb_build_array(jsonb_build_object(''variant_id'',''50000000-0000-0000-0000-000000000001'',''quantity'',1)),''TRANSFER'')',
    'Localização em contagem');

  -- Gravar uma divergência no item do SKU-001
  SELECT id INTO v_item FROM public.inventory_count_items
    WHERE inventory_count_id = v_cid AND variant_id = '50000000-0000-0000-0000-000000000001'
    ORDER BY id LIMIT 1;
  v := public.inventory_save_count_item('20000000-0000-0000-0000-000000000001', v_cid, v_item, v_before + 7);
  PERFORM pg_temp.check('E5 contagem gravada (diferença +7)', (v->>'ok')::boolean
    AND (v->>'difference')::numeric = 7, 'diff=' || v->>'difference');

  -- Concluir: gera ADJUSTMENT_IN +7
  v_res := public.inventory_complete_count('20000000-0000-0000-0000-000000000001', v_cid);
  PERFORM pg_temp.check('E6 contagem concluída com 1 ajuste', (v_res->>'adjustments_created')::int = 1,
    'ajustes=' || v_res->>'adjustments_created');
  v_after := public.inventory_get_balance('20000000-0000-0000-0000-000000000001',
    '50000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');
  PERFORM pg_temp.check('E7 saldo incorporou +7', v_after = v_before + 7, v_before || ' -> ' || v_after);
  PERFORM pg_temp.check('E8 contagem ficou COMPLETED',
    (SELECT status='COMPLETED' FROM public.inventory_counts WHERE id=v_cid));

  -- Localização liberada após conclusão
  v := public.inventory_post_movement(
    '20000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000002', 'ADJUSTMENT_IN', 1, 'pós-contagem');
  PERFORM pg_temp.check('E9 localização liberada após concluir', NOT (v->>'deduped')::boolean);

  -- Cancelar contagem
  v := public.inventory_start_count('20000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001');
  v_cid := (v->>'id')::uuid;
  PERFORM pg_temp.expect_error('E10 bloqueio durante contagem na fábrica',
    'SELECT public.inventory_post_movement(''20000000-0000-0000-0000-000000000001'',''50000000-0000-0000-0000-000000000001'',''30000000-0000-0000-0000-000000000001'',''ADJUSTMENT_IN'',5,''x'')',
    'Localização em contagem');
  v := public.inventory_cancel_count('20000000-0000-0000-0000-000000000001', v_cid);
  PERFORM pg_temp.check('E11 contagem cancelada', (v->>'ok')::boolean);
  PERFORM pg_temp.check('E12 cancelamento libera localização',
    (SELECT status='CANCELED' FROM public.inventory_counts WHERE id=v_cid));

  -- Concluir sem itens contados
  v := public.inventory_start_count('20000000-0000-0000-0000-000000000001',
    '30000000-0000-0000-0000-000000000001');
  v_cid := (v->>'id')::uuid;
  PERFORM pg_temp.expect_error('E13 concluir sem itens é rejeitado',
    format('SELECT public.inventory_complete_count(''20000000-0000-0000-0000-000000000001'', %L)', v_cid),
    'Conte ao menos um item');
  v := public.inventory_cancel_count('20000000-0000-0000-0000-000000000001', v_cid);
  PERFORM pg_temp.check('E14 cancelamento da contagem vazia ok', (v->>'ok')::boolean);
END $$;
COMMIT;

